// AGENT in the sub-workflow - and the node that seeds this sub-execution.
//
// A sub-workflow runs under its OWN n8n execution id, so it inherits nothing
// from the parent: the proxy's execution correlation is scoped to one
// execution by design. Whatever identity the sub-workflow needs has to arrive
// in its input and be declared again here.
//
// Which is why this is a LangChain Code node. n8n's native AI Agent node has no
// field for run metadata, so a sub-workflow built only from Agent nodes cannot
// attribute itself at all - its traces reach Langfuse with no session. One node
// of this kind per execution is enough; the native agents beside it inherit via
// the sub-execution's own id.

const { ChatPromptTemplate } = require('@langchain/core/prompts');
const { StringOutputParser } = require('@langchain/core/output_parsers');

const body = $input.first().json;

const sessionId = body.sessionId;
// Carried, never minted. This sub-workflow is part of a message that already
// has an id; minting one here would split the message across two traces.
const msgId = body.msg_id;
if (!msgId) throw new Error('msg_id must be supplied by the calling workflow');
const userId    = body.user_id || 'sixdee';
const chatInput = body.chatInput || '';

const llm = await this.getInputConnectionData('ai_languageModel', 0);

const prompt = ChatPromptTemplate.fromMessages([
  ['system', 'You are a sub-workflow specialist. Answer in one sentence.'],
  ['human', '{question}'],
]);

const chain = prompt.pipe(llm).pipe(new StringOutputParser()).withConfig({
  runName: `subflow ${msgId}`,
  tags: ['node:crm', `msg:${msgId}`, 'agent:subflow'],
  metadata: {
    node: 'crm',
    session_id: sessionId,
    msg_id: msgId,
    user_id: userId,
    workflow_name: 'Support Sub-agent',
    agent: 'subflow',
    // This sub-workflow runs under its own n8n execution id - that is the
    // agent-level identity, and it differs from the caller's on purpose.
    execution_id: String($execution.id),
    node_execution_id: `subflow#${$execution.id}`,
    parent_execution_id: body.parent_execution_id || null,
  },
});

const answer = await chain.invoke({ question: chatInput });

return [{ json: Object.assign({}, body, { subAnswer: answer }) }];
